mapper.select:
select rule_id, rule_name, risk_level, status, condition_json, remark, create_by, create_time, update_by, update_time
from agentsec_alert_rule

    and rule_name like concat('%', #{ruleName}, '%')
    and risk_level = #{riskLevel}
    and status = #{status}

order by create_time desc

select rule_id, rule_name, risk_level, status, condition_json, remark, create_by, create_time, update_by, update_time
from agentsec_alert_rule
where rule_id = #{ruleId}

mapper.insert:
