)

mapper.update:
update agentsec_alert_rule
rule_name = #{ruleName}, risk_level = #{riskLevel}, status = #{status}, condition_json = #{conditionJson}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
